insert into public.transcripts (video_id, owner_id, text, language, model, duration_s, status) values
('a0000000-0000-4000-8000-000000000000', '00000000-0000-0000-0000-000000000001', 'You can fix your resume in 4 days. The problem is that most advice ignores how your resume actually behaves. Everyone says to double down on applying on LinkedIn, and that is exactly backwards. Step one, audit your resume. Step two, cut applying on LinkedIn. Step three, track it for 4 days. Save this so you actually try it, and follow for part two.', 'en', 'whisper-1', 67, 'ok'),
('a0000000-0000-4000-8000-000000000001', '00000000-0000-0000-0000-000000000001', 'Nobody talks about the 5-second trick for ChatGPT. Quick context: I have been doing this for years and I kept getting it wrong. Save this so you actually try it, and follow for part two.', 'en', 'whisper-1', 48, 'ok'),
('a0000000-0000-4000-8000-000000000002', '00000000-0000-0000-0000-000000000001', '7 ways to fix your hook this week. Step one, audit your hook. Step two, cut posting daily. Step three, track it for 7 days. For example, a friend tried this last month and got ten thousand views without changing anything else.', 'en', 'whisper-1', 67, 'ok'),
('a0000000-0000-4000-8000-000000000003', '00000000-0000-0000-0000-000000000001', 'Stop prompting from scratch right now if you want a usable draft. Save this so you actually try it, and follow for part two. Side note, this works even if you hate prompting from scratch.', 'en', 'whisper-1', 68, 'ok'),
('a0000000-0000-4000-8000-000000000004', '00000000-0000-0000-0000-000000000001', 'prompting from scratch is the single fastest path to a usable draft. Quick context: I have been doing this for years and I kept getting it wrong. Everyone says to double down on prompting from scratch, and that is exactly backwards. Step one, audit ChatGPT. Step two, cut prompting from scratch. Step three, track it for 5 days. Save this so you actually try it, and follow for part two.', 'en', 'whisper-1', 29, 'ok'),
('a0000000-0000-4000-8000-000000000005', '00000000-0000-0000-0000-000000000001', 'Nobody talks about the 2-second trick for your sleep. Quick context: I have been doing this for years and I kept getting it wrong. Step one, audit your sleep. Step two, cut skipping breakfast. Step three, track it for 2 days. For example, a friend tried this last month and got stable energy without changing anything else.', 'en', 'whisper-1', 53, 'ok'),
('a0000000-0000-4000-8000-000000000006', '00000000-0000-0000-0000-000000000001', 'Last year applying on LinkedIn nearly broke me. Quick context: I have been doing this for years and I kept getting it wrong. Step one, audit your resume. Step two, cut applying on LinkedIn. Step three, track it for 4 days. For example, a friend tried this last month and got a real interview without changing anything else. Do this and a real interview stops being a goal and becomes your baseline. Save this so you actually try it, and follow for part two.', 'en', 'whisper-1', 66, 'ok'),
('a0000000-0000-4000-8000-000000000007', '00000000-0000-0000-0000-000000000001', 'Never touch your hook before you hear this. When I switched, my results went from nothing to ten thousand views in 7 weeks. Do this and ten thousand views stops being a goal and becomes your baseline.', 'en', 'whisper-1', 20, 'ok'),
('a0000000-0000-4000-8000-000000000008', '00000000-0000-0000-0000-000000000001', 'time blocking is the single fastest path to a calm week. Quick context: I have been doing this for years and I kept getting it wrong. When I switched, my results went from nothing to a calm week in 3 weeks. Step one, audit your to-do list. Step two, cut time blocking. Step three, track it for 3 days. For example, a friend tried this last month and got a calm week without changing anything else.', 'en', 'whisper-1', 29, 'ok'),
('a0000000-0000-4000-8000-000000000009', '00000000-0000-0000-0000-000000000001', 'Forget your hook. It does not matter. For example, a friend tried this last month and got ten thousand views without changing anything else. Side note, this works even if you hate posting daily.', 'en', 'whisper-1', 20, 'ok'),
('a0000000-0000-4000-8000-000000000010', '00000000-0000-0000-0000-000000000001', 'There is one thing about budgeting apps I wish I knew earlier. Quick context: I have been doing this for years and I kept getting it wrong. Side note, this works even if you hate budgeting apps.', 'en', 'whisper-1', 46, 'ok'),
('a0000000-0000-4000-8000-000000000011', '00000000-0000-0000-0000-000000000001', 'There is one thing about prompting from scratch I wish I knew earlier. Step one, audit ChatGPT. Step two, cut prompting from scratch. Step three, track it for 5 days. For example, a friend tried this last month and got a usable draft without changing anything else. Save this so you actually try it, and follow for part two. Side note, this works even if you hate prompting from scratch.', 'en', 'whisper-1', 44, 'ok'),
('a0000000-0000-4000-8000-000000000012', '00000000-0000-0000-0000-000000000001', 'Here are 3 rules for time blocking that actually work. Quick context: I have been doing this for years and I kept getting it wrong. The problem is that most advice ignores how your to-do list actually behaves. Step one, audit your to-do list. Step two, cut time blocking. Step three, track it for 3 days. Save this so you actually try it, and follow for part two. Side note, this works even if you hate time blocking.', 'en', 'whisper-1', 50, 'ok'),
('a0000000-0000-4000-8000-000000000013', '00000000-0000-0000-0000-000000000001', 'Stop prompting from scratch right now if you want a usable draft. When I switched, my results went from nothing to a usable draft in 5 weeks. Step one, audit ChatGPT. Step two, cut prompting from scratch. Step three, track it for 5 days. Do this and a usable draft stops being a goal and becomes your baseline. Save this so you actually try it, and follow for part two. Side note, this works even if you hate prompting from scratch.', 'en', 'whisper-1', 55, 'ok'),
('a0000000-0000-4000-8000-000000000014', '00000000-0000-0000-0000-000000000001', 'Why does ChatGPT keep failing you? Quick context: I have been doing this for years and I kept getting it wrong. The problem is that most advice ignores how ChatGPT actually behaves. Do this and a usable draft stops being a goal and becomes your baseline.', 'en', 'whisper-1', 60, 'ok'),
('a0000000-0000-4000-8000-000000000015', '00000000-0000-0000-0000-000000000001', 'You, yes you, need to stop obsessing over your hook. When I switched, my results went from nothing to ten thousand views in 7 weeks. For example, a friend tried this last month and got ten thousand views without changing anything else. Side note, this works even if you hate posting daily.', 'en', 'whisper-1', 30, 'ok'),
